INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20CTWZR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $\\$74$ is on sale for $25\\%$ off. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$18.50$"},{"key":"B","text":"$\\$49.00$"},{"key":"C","text":"$\\$55.50$"},{"key":"D","text":"$\\$59.00$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $25\\%$ discount on $\\$74$ is $0.25 \\times 74 = \\$18.50$. The sale price is $74 - 18.50 = \\$55.50$. The answer $\\$18.50$ gives only the discount amount, not the sale price. The answer $\\$49.00$ results from subtracting $25$ directly from $74$ instead of computing $25\\%$. The answer $\\$59.00$ comes from computing $20\\%$ off instead of $25\\%$ off.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20F3MQN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees found that 74 drink coffee only, 53 drink tea only, 31 drink both coffee and tea, and the rest drink neither. If an employee is selected at random from those who drink coffee, what is the probability that the employee also drinks tea?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{31}{200}\\)"},{"key":"B","text":"\\(\\dfrac{31}{105}\\)"},{"key":"C","text":"\\(\\dfrac{31}{84}\\)"},{"key":"D","text":"\\(\\dfrac{31}{127}\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The number of employees who drink coffee is those who drink coffee only plus those who drink both: \\(74 + 31 = 105\\). The conditional probability of also drinking tea given that the employee drinks coffee is \\(\\dfrac{31}{105}\\). The answer \\(\\dfrac{31}{200}\\) incorrectly uses the total number of employees as the denominator, ignoring the conditional restriction. The answer \\(\\dfrac{31}{84}\\) uses \\(53 + 31 = 84\\), which is the number of tea drinkers, as the denominator instead of the coffee drinkers. The answer \\(\\dfrac{31}{127}\\) uses \\(74 + 53 = 127\\) as the denominator, adding the two "only" groups without including the overlap.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20IRDCZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution to the equation \\(x^2 - 3x - 28 = 0\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factoring the quadratic: \\(x^2 - 3x - 28 = (x - 7)(x + 4) = 0\\). Setting each factor equal to zero gives \\(x = 7\\) or \\(x = -4\\). The positive solution is \\(7\\).', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21DYFGN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor standing at point $P$ observes the top of a building at an angle of elevation of $37°$. After walking $40$ meters directly toward the building on level ground, the surveyor observes the top at an angle of elevation of $58°$. Which of the following expressions gives the height of the building, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{40}{\\tan(58°) - \\tan(37°)}$"},{"key":"B","text":"$\\frac{40}{\\cot(37°) - \\cot(58°)}$"},{"key":"C","text":"$\\frac{40\\tan(37°)}{\\tan(58°)}$"},{"key":"D","text":"$40(\\tan(58°) - \\tan(37°))$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the height of the building and $d$ be the horizontal distance from the second observation point to the base. From the second point, $\\tan(58°) = \\frac{h}{d}$, so $d = \\frac{h}{\\tan(58°)}$. From the first point, $\\tan(37°) = \\frac{h}{d + 40}$, so $d + 40 = \\frac{h}{\\tan(37°)}$. Subtracting: $40 = \\frac{h}{\\tan(37°)} - \\frac{h}{\\tan(58°)} = h(\\cot(37°) - \\cot(58°))$. Solving gives $h = \\frac{40}{\\cot(37°) - \\cot(58°)}$. The expression $\\frac{40}{\\tan(58°) - \\tan(37°)}$ incorrectly uses tangent where cotangent is needed, misapplying the reciprocal relationship. The expression $\\frac{40\\tan(37°)}{\\tan(58°)}$ oversimplifies the relationship by treating the two triangles as directly proportional. The expression $40(\\tan(58°) - \\tan(37°))$ incorrectly multiplies rather than divides.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22PR26Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $141°$. If the measure of angle $P$ is twice the measure of angle $Q$, what is the measure, in degrees, of angle $P$?', NULL, $lyceon_json$[{"key":"A","text":"$39°$"},{"key":"B","text":"$47°$"},{"key":"C","text":"$94°$"},{"key":"D","text":"$96°$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, the exterior angle at $R$ equals the sum of the two non-adjacent interior angles: $\\angle P + \\angle Q = 141°$. Since $\\angle P = 2\\angle Q$, substituting gives $2\\angle Q + \\angle Q = 141°$, so $3\\angle Q = 141°$ and $\\angle Q = 47°$. Therefore $\\angle P = 2(47°) = 94°$. The answer $39°$ comes from using the interior angle at $R$ ($180° - 141° = 39°$) as the answer, confusing it with the requested angle. The answer $47°$ is the measure of $\\angle Q$, not $\\angle P$. The answer $96°$ results from an arithmetic slip, such as dividing $141$ by $3$ incorrectly as $48$ and then doubling.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
