INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23HZ8HC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = 2.3x + 14.7$, where $x$ represents the number of weeks and $y$ represents the total number of items sold. According to this model, what is the best interpretation of the slope $2.3$?', NULL, $lyceon_json$[{"key":"A","text":"The model predicts an increase of $2.3$ items sold per week."},{"key":"B","text":"The model predicts that $2.3$ items are sold in week $0$."},{"key":"C","text":"The model predicts a total of $2.3$ items sold after $14.7$ weeks."},{"key":"D","text":"The model predicts an increase of $14.7$ items sold every $2.3$ weeks."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = 2.3x + 14.7$, the slope $2.3$ represents the rate of change: for each additional week, the model predicts an increase of $2.3$ items sold. The answer stating $2.3$ items are sold in week $0$ confuses the slope with the $y$-intercept. The answer stating $2.3$ items sold after $14.7$ weeks reverses the roles of the slope and intercept. The answer involving $14.7$ items every $2.3$ weeks misreads both the slope and intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23YIMCC', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ in the equation $\\frac{5x + 13}{3} - \\frac{2x - 1}{7} = \\frac{23x + 106}{21}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Multiplying every term by 21 (the LCD of 3, 7, and 21) gives $7(5x + 13) - 3(2x - 1) = 23x + 106$. Expanding the left side: $35x + 91 - 6x + 3 = 23x + 106$. Combining like terms: $29x + 94 = 23x + 106$. Subtracting $23x$ from both sides: $6x + 94 = 106$. Subtracting 94: $6x = 12$. Dividing by 6: $x = 2$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25GMO5B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $5$ participants in a study are $23$, $29$, $31$, $31$, and $41$. What is the median age of the participants?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$30$"},{"key":"C","text":"$31$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'C', NULL, E'The data in ascending order are $23, 29, 31, 31, 41$. With $5$ values, the median is the $3$rd value, which is $31$. The answer $29$ confuses the median with the $2$nd value in the sorted list. The answer $30$ incorrectly averages $29$ and $31$ as if there were an even number of data points. The answer $32$ may come from miscounting positions or averaging $31$ and $33$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25HKGQ2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'In the $xy$-plane, a circle has equation $x^2 + y^2 - 6x + 8y = 0$. What is the length of the chord of this circle that lies along the line $y = -1$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'First, rewrite the equation in standard form by completing the square: $(x^2 - 6x + 9) + (y^2 + 8y + 16) = 9 + 16$, giving $(x - 3)^2 + (y + 4)^2 = 25$. The circle has center $(3, -4)$ and radius $5$. The perpendicular distance from the center $(3, -4)$ to the line $y = -1$ is $|-4 - (-1)| = |-3| = 3$. Using the relationship between the radius, the distance from the center to the chord, and the half-chord length: half-chord $= \\sqrt{r^2 - d^2} = \\sqrt{25 - 9} = \\sqrt{16} = 4$. The full chord length is $2 \\times 4 = 8$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27B6358', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function \\(g\\) is defined by \\(g(x) = 4x^2 - 7\\). What is the value of \\(g(-3)\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(29\\)"},{"key":"B","text":"\\(-43\\)"},{"key":"C","text":"\\(43\\)"},{"key":"D","text":"\\(-29\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting \\(x = -3\\): \\(g(-3) = 4(-3)^2 - 7 = 4(9) - 7 = 36 - 7 = 29\\). The distractor \\(-43\\) results from incorrectly computing \\((-3)^2\\) as \\(-9\\) instead of \\(9\\), giving \\(4(-9) - 7 = -36 - 7 = -43\\). The distractor \\(43\\) comes from adding 7 instead of subtracting, giving \\(36 + 7 = 43\\). The distractor \\(-29\\) applies a sign error to the entire result.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27XHD92', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A truck travels $187$ miles using $11$ gallons of diesel. A second truck travels $221$ miles using $13$ gallons of the same diesel. What is the positive difference, in miles per gallon, between the fuel efficiencies of the two trucks?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0', ARRAY['0'], E'The first truck''s fuel efficiency is $\\frac{187}{11} = 17$ miles per gallon. The second truck''s fuel efficiency is $\\frac{221}{13} = 17$ miles per gallon. The positive difference is $17 - 17 = 0$ miles per gallon. Students who rush may compute only one rate or assume the truck with more miles traveled must be more efficient without calculating. The key insight is that despite different distances and fuel amounts, both trucks have identical efficiency.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27Z6D0H', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to \\(7x^2 - 3x + 4 - (2x^2 + 5x - 9)\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(5x^2 - 8x + 13\\)"},{"key":"B","text":"\\(5x^2 + 2x - 5\\)"},{"key":"C","text":"\\(9x^2 - 8x + 13\\)"},{"key":"D","text":"\\(5x^2 - 8x - 5\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the negative sign gives \\(7x^2 - 3x + 4 - 2x^2 - 5x + 9\\). Combining like terms: \\(7x^2 - 2x^2 = 5x^2\\), \\(-3x - 5x = -8x\\), and \\(4 + 9 = 13\\), yielding \\(5x^2 - 8x + 13\\). The distractor \\(5x^2 + 2x - 5\\) results from failing to distribute the negative sign to all terms in the second group. The distractor \\(9x^2 - 8x + 13\\) incorrectly adds the \\(x^2\\) coefficients instead of subtracting. The distractor \\(5x^2 - 8x - 5\\) incorrectly computes \\(4 - 9 = -5\\) instead of \\(4 + 9 = 13\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28I59AS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$, the right angle is at vertex $K$. If $JL = 37$ and $JK = 35$, what is the value of $\\tan(L)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{12}{35}$"},{"key":"B","text":"$\\frac{12}{37}$"},{"key":"C","text":"$\\frac{35}{12}$"},{"key":"D","text":"$\\frac{35}{37}$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, find $KL$ using the Pythagorean theorem: $KL = \\sqrt{JL^2 - JK^2} = \\sqrt{37^2 - 35^2} = \\sqrt{1369 - 1225} = \\sqrt{144} = 12$. For angle $L$, the side opposite is $JK = 35$ and the side adjacent is $KL = 12$, so $\\tan(L) = \\frac{35}{12}$. The value $\\frac{12}{35}$ results from inverting the tangent ratio (adjacent over opposite instead of opposite over adjacent). The value $\\frac{12}{37}$ is $\\cos(L)$, not $\\tan(L)$, reflecting confusion between trigonometric ratios. The value $\\frac{35}{37}$ is $\\sin(L)$, which uses the hypotenuse in the denominator instead of the adjacent side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A4MIQW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to \\(\\frac{x^2 + 11x + 28}{x^2 - 49}\\) for \\(x \\neq \\pm 7\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\frac{x + 4}{x - 7}\\)"},{"key":"B","text":"\\(\\frac{x + 4}{x + 7}\\)"},{"key":"C","text":"\\(\\frac{x - 4}{x - 7}\\)"},{"key":"D","text":"\\(\\frac{x + 7}{x - 7}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: \\(x^2 + 11x + 28 = (x + 4)(x + 7)\\). Factor the denominator as a difference of squares: \\(x^2 - 49 = (x + 7)(x - 7)\\). Canceling the common factor \\((x + 7)\\) yields \\(\\frac{x + 4}{x - 7}\\). The distractor \\(\\frac{x + 4}{x + 7}\\) cancels the wrong factor, removing \\((x - 7)\\) instead of \\((x + 7)\\). The distractor \\(\\frac{x - 4}{x - 7}\\) introduces a sign error in the numerator factor. The distractor \\(\\frac{x + 7}{x - 7}\\) incorrectly cancels \\((x + 4)\\) from the numerator, which is not a common factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A7DUSL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a strong positive linear association between the number of hours studied and test score. Which of the following best describes this relationship?', NULL, $lyceon_json$[{"key":"A","text":"As hours studied increases, test score tends to decrease."},{"key":"B","text":"As hours studied increases, test score tends to increase."},{"key":"C","text":"There is no consistent relationship between hours studied and test score."},{"key":"D","text":"As hours studied increases, test score remains constant."}]$lyceon_json$::jsonb, 'B', NULL, E'A strong positive linear association means that as one variable increases, the other tends to increase as well. Therefore, as hours studied increases, test score tends to increase. The answer stating test score tends to decrease describes a negative association. The answer stating no consistent relationship describes no association. The answer stating test score remains constant describes no association between the variables.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BFJLIF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set of $8$ values has a mean of $17$. When a $9$th value is added, the mean becomes $19$. What is the $9$th value?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$27$"},{"key":"C","text":"$35$"},{"key":"D","text":"$38$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of the original $8$ values is $8 \\times 17 = 136$. With the $9$th value added, the new sum is $9 \\times 19 = 171$. The $9$th value is $171 - 136 = 35$. The answer $21$ comes from simply adding the mean increase of $2$ to the new mean $19$. The answer $27$ results from a setup error such as computing $9 \\times 19 - 8 \\times 18$. The answer $38$ comes from an arithmetic slip such as computing $8 \\times 17 = 133$ instead of $136$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BQ7CB6', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A gym charges a one-time registration fee of $\\$37$ and a monthly membership fee of $\\$29$. Which function $f(m)$ gives the total cost, in dollars, for $m$ months of membership?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 29m + 37$"},{"key":"B","text":"$f(m) = 37m + 29$"},{"key":"C","text":"$f(m) = 66m$"},{"key":"D","text":"$f(m) = 29m - 37$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the one-time fee plus the monthly fee times the number of months: $f(m) = 29m + 37$. The function $f(m) = 37m + 29$ swaps the registration fee and monthly fee in the equation, treating $37$ as the recurring cost. The function $f(m) = 66m$ incorrectly adds the two fees and treats the sum as a monthly rate, ignoring that the registration fee is one-time. The function $f(m) = 29m - 37$ uses the correct monthly rate but subtracts the registration fee instead of adding it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BUP16B', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same large population. Sample 1 has 250 respondents and finds 44% favor a policy change with a margin of error of 6.2 percentage points. Sample 2 has 1,000 respondents and finds 41% favor the policy change with a margin of error of 3.1 percentage points. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The two samples contradict each other, so neither result is reliable."},{"key":"B","text":"The confidence intervals from the two samples overlap, so the results are consistent with each other."},{"key":"C","text":"Sample 2 is more reliable because it has a larger proportion opposing the policy change."},{"key":"D","text":"The true population proportion must be exactly 41% because Sample 2 is larger."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample 1 gives a confidence interval of \\(44\\% \\pm 6.2\\%\\), or 37.8% to 50.2%. Sample 2 gives \\(41\\% \\pm 3.1\\%\\), or 37.9% to 44.1%. These intervals overlap substantially (from about 37.9% to 44.1%), so the two results are consistent — different sample proportions do not imply contradiction when their confidence intervals overlap. The claim that the samples contradict each other ignores that the intervals overlap. The claim that Sample 2 is more reliable because its proportion is lower confuses the magnitude of the estimate with precision; reliability comes from the smaller margin of error due to larger sample size, not from the proportion itself. The claim that the true proportion must be exactly 41% treats the larger sample''s point estimate as the exact population parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C1Y8AD', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = \\frac{11x - 47}{3}$. If $g(a) = 2a - 9$, what is the value of $g(2a)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{41}{3}$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$\\frac{-5}{3}$"},{"key":"D","text":"$\\frac{65}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First solve for $a$: $\\frac{11a - 47}{3} = 2a - 9$. Multiplying both sides by 3: $11a - 47 = 6a - 27$. So $5a = 20$, giving $a = 4$. Then $2a = 8$, and $g(8) = \\frac{11(8) - 47}{3} = \\frac{88 - 47}{3} = \\frac{41}{3}$. The value $-1$ comes from computing $g(a) = 2(4) - 9 = -1$ but reporting that instead of $g(2a)$. The value $\\frac{-5}{3}$ results from an arithmetic error when evaluating $88 - 47$, obtaining $-5$ instead of $41$. The value $\\frac{65}{3}$ results from substituting $2a + 4 = 12$ instead of $2a = 8$ into $g$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CTD72T', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A student has at most $\\$47$ to spend on notebooks that cost $\\$3$ each and a binder that costs $\\$11$. What is the maximum number of notebooks the student can buy?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'Let $n$ represent the number of notebooks. The total cost is $3n + 11$, and this must be at most $47$: $$3n + 11 \\leq 47$$ Subtracting $11$ from both sides gives $3n \\leq 36$. Dividing both sides by $3$ gives $n \\leq 12$. Since $n$ must be a whole number, the maximum number of notebooks is $12$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CYD9HR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university study randomly selects 300 students from its enrollment of 8,400 and randomly assigns them to either a meditation program or a study-skills workshop for one semester. At the end of the semester, the meditation group has a statistically significantly higher GPA increase than the workshop group. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The meditation program caused a greater GPA increase than the study-skills workshop among students at this university."},{"key":"B","text":"The meditation program caused a greater GPA increase than the study-skills workshop for college students in general."},{"key":"C","text":"There is an association between meditation and higher GPA, but it cannot be concluded that meditation caused the increase."},{"key":"D","text":"The results are invalid because students were not allowed to choose their own group."}]$lyceon_json$::jsonb, 'A', NULL, E'This study uses both random selection (from the university''s 8,400 students) and random assignment (to meditation or workshop), so it supports a causal conclusion that generalizes to students at this university. The claim about college students in general overgeneralizes — the random selection was from one university, not from all college students. The claim that only an association can be established ignores that random assignment was used, which controls for confounding variables and supports causation. The claim that the results are invalid because students could not choose their group misunderstands experimental design; random assignment is a deliberate feature that strengthens causal inference, not a flaw.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DJNXT5', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$3x + 2y = 19$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E3B8ZU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(3, -11)$ and $(-5, 13)$. What is the equation of this line in standard form?', NULL, $lyceon_json$[{"key":"A","text":"$3x + y = -2$"},{"key":"B","text":"$3x - y = 20$"},{"key":"C","text":"$x + 3y = -30$"},{"key":"D","text":"$3x + y = 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{13 - (-11)}{-5 - 3} = \\frac{24}{-8} = -3$. Using point-slope form with $(3, -11)$: $y + 11 = -3(x - 3)$, so $y + 11 = -3x + 9$, giving $y = -3x - 2$. In standard form: $3x + y = -2$. The equation $3x - y = 20$ results from a sign error when rearranging to standard form. The equation $x + 3y = -30$ comes from inverting the slope to $-\\frac{1}{3}$. The equation $3x + y = 2$ has the correct slope but an arithmetic mistake with the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EH9EG1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone is inscribed in a hemisphere of radius $6$ such that the base of the cone coincides with the flat circular face of the hemisphere. What is the volume of the region inside the hemisphere but outside the cone?', NULL, $lyceon_json$[{"key":"A","text":"$36\\pi$"},{"key":"B","text":"$72\\pi$"},{"key":"C","text":"$144\\pi$"},{"key":"D","text":"$216\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The hemisphere has radius $6$. Its volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(216) = 144\\pi$. The inscribed cone shares the same circular base (radius $6$) and has height equal to the hemisphere''s radius ($6$). The cone''s volume is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(36)(6) = 72\\pi$. The region inside the hemisphere but outside the cone has volume $144\\pi - 72\\pi = 72\\pi$. The value $36\\pi$ results from a computational error such as halving the cone volume or miscalculating the subtraction. The value $144\\pi$ is the hemisphere volume alone, without subtracting the cone. The value $216\\pi$ equals $\\pi r^3$ without the proper coefficient, reflecting a gap in the volume formula for a hemisphere.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FFWAE6', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'If $7x - 13 > 22$, which of the following represents all possible values of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$x > 5$"},{"key":"B","text":"$x > 3$"},{"key":"C","text":"$x < 5$"},{"key":"D","text":"$x > 7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $13$ to both sides gives $7x > 35$. Dividing both sides by $7$ gives $x > 5$. The distractor $x > 3$ results from an arithmetic error when dividing $21$ by $7$ instead of $35$ by $7$. The distractor $x < 5$ reverses the inequality direction incorrectly. The distractor $x > 7$ comes from incorrectly dividing $35$ by $5$ instead of by $7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H5XESW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The system of equations \\(y = x^2 - 6x + 11\\) and \\(y = 2x - 3\\) has two solutions. What is the sum of the \\(x\\)-coordinates of these solutions?', NULL, $lyceon_json$[{"key":"A","text":"\\(6\\)"},{"key":"B","text":"\\(8\\)"},{"key":"C","text":"\\(10\\)"},{"key":"D","text":"\\(14\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal: \\(x^2 - 6x + 11 = 2x - 3\\), which simplifies to \\(x^2 - 8x + 14 = 0\\). By Vieta''s formulas, the sum of the roots equals \\(-(-8)/1 = 8\\). The distractor 6 comes from using only the coefficient of \\(x\\) in the original quadratic (\\(-6x\\)) without incorporating the linear equation. The distractor 10 results from an error in combining the \\(x\\) terms, such as subtracting incorrectly to get \\(-10x\\). The distractor 14 confuses the sum of the roots with the constant term of the resulting equation.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HG0V4U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up a product by $40\\%$ over its cost, and then offers a $30\\%$ discount on the marked-up price during a sale. If the sale price is $\\$58.80$, what was the original cost, in dollars, of the product?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let $c$ be the original cost. The marked-up price is $1.4c$. After a $30\\%$ discount, the sale price is $0.70 \\times 1.4c = 0.98c$. Setting $0.98c = 58.80$ gives $c = \\frac{58.80}{0.98} = 60$. The original cost was $\\$60$. A common error is assuming the $40\\%$ markup and $30\\%$ discount cancel to a net $10\\%$ markup, or applying the percentages additively rather than multiplicatively.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IAE76A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains 7 red marbles, 11 blue marbles, and 5 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{11}{23}\\)"},{"key":"B","text":"\\(\\dfrac{7}{23}\\)"},{"key":"C","text":"\\(\\dfrac{5}{23}\\)"},{"key":"D","text":"\\(\\dfrac{11}{12}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is \\(7 + 11 + 5 = 23\\). The probability of selecting a blue marble is \\(\\dfrac{11}{23}\\). The answer \\(\\dfrac{7}{23}\\) incorrectly counts only the red marbles in the numerator. The answer \\(\\dfrac{5}{23}\\) incorrectly counts only the green marbles. The answer \\(\\dfrac{11}{12}\\) uses the sum of the non-blue marbles as the denominator instead of the total, reflecting a misunderstanding of basic probability.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IFZNTU', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $9x + 14 = 77$?', NULL, $lyceon_json$[{"key":"A","text":"5"},{"key":"B","text":"7"},{"key":"C","text":"9"},{"key":"D","text":"63"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtract 14 from both sides: $9x = 63$. Divide by 9: $x = 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JMLU61', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'After a $22\\%$ increase, the enrollment at a school is $6{,}588$. What was the enrollment before the increase?', NULL, $lyceon_json$[{"key":"A","text":"$5{,}400$"},{"key":"B","text":"$5{,}139$"},{"key":"C","text":"$5{,}988$"},{"key":"D","text":"$6{,}100$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $P$ be the original enrollment. Then $1.22P = 6588$, so $P = 6588 / 1.22 = 5400$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JZPZVE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $7x - 4y = 52$. Line $q$ is perpendicular to line $p$ and passes through the point $(14, -3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'First, rewrite line $p$ in slope-intercept form: $-4y = -7x + 52$, so $y = \\frac{7}{4}x - 13$. The slope of line $p$ is $\\frac{7}{4}$. A line perpendicular to $p$ has slope $-\\frac{4}{7}$. Using point-slope form with $(14, -3)$: $y + 3 = -\\frac{4}{7}(x - 14)$. Simplifying: $y + 3 = -\\frac{4}{7}x + 8$, giving $y = -\\frac{4}{7}x + 5$. The $y$-intercept is $5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KFWATH', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$2x + y = 17$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KG05TQ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to \\(\\frac{6x^3 - 15x^2 + 9x}{3x}\\) for \\(x \\neq 0\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(2x^2 - 5x + 3\\)"},{"key":"B","text":"\\(2x^3 - 5x^2 + 3x\\)"},{"key":"C","text":"\\(2x^2 - 5x + 9\\)"},{"key":"D","text":"\\(6x^2 - 15x + 9\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term of the numerator by \\(3x\\): \\(\\frac{6x^3}{3x} = 2x^2\\), \\(\\frac{-15x^2}{3x} = -5x\\), and \\(\\frac{9x}{3x} = 3\\). The result is \\(2x^2 - 5x + 3\\). The distractor \\(2x^3 - 5x^2 + 3x\\) divides only the coefficients by 3 without reducing the exponents by the division of \\(x\\). The distractor \\(2x^2 - 5x + 9\\) correctly divides the first two terms but fails to divide the last coefficient by 3. The distractor \\(6x^2 - 15x + 9\\) divides only by \\(x\\), ignoring the factor of 3 in the denominator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LCTHGM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'What is the area, in square centimeters, of a circle with a radius of $13$ cm?', NULL, $lyceon_json$[{"key":"A","text":"$26\\pi$"},{"key":"B","text":"$169$"},{"key":"C","text":"$169\\pi$"},{"key":"D","text":"$676\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(13)^2 = 169\\pi$ square centimeters. The value $26\\pi$ results from computing the circumference $2\\pi r = 2\\pi(13) = 26\\pi$ instead of the area, confusing the two formulas. The value $169$ correctly squares the radius but omits $\\pi$ from the formula. The value $676\\pi$ results from squaring the diameter ($26^2 = 676$) instead of the radius, using $\\pi d^2$ rather than $\\pi r^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NEHLVM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $5$ cm and a height of $\\frac{18}{\\pi}$ cm. What is the volume of the cylinder, in cubic centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '450', ARRAY['450'], E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting the given values: $V = \\pi(5)^2\\left(\\frac{18}{\\pi}\\right) = \\pi(25)\\left(\\frac{18}{\\pi}\\right) = 25 \\times 18 = 450$. The $\\pi$ in the formula cancels with the $\\pi$ in the denominator of the height, yielding a whole-number volume.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NUQXN9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A teacher records quiz scores for $6$ students: $62$, $71$, $75$, $81$, $88$, and $93$. If the teacher removes the lowest score and the highest score, by how much does the mean of the remaining scores change compared to the mean of all $6$ scores?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases by $\\frac{1}{4}$"},{"key":"B","text":"The mean does not change"},{"key":"C","text":"The mean increases by $\\frac{5}{12}$"},{"key":"D","text":"The mean increases by $\\frac{7}{4}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of all $6$ scores is $62 + 71 + 75 + 81 + 88 + 93 = 470$, and the mean is $\\frac{470}{6} = \\frac{235}{3}$. Removing the lowest ($62$) and highest ($93$) gives a sum of $470 - 62 - 93 = 315$ for $4$ scores, with mean $\\frac{315}{4}$. The change is $\\frac{315}{4} - \\frac{235}{3} = \\frac{945}{12} - \\frac{940}{12} = \\frac{5}{12}$. Since the result is positive, the mean increases by $\\frac{5}{12}$. The answer stating the mean decreases by $\\frac{1}{4}$ results from a sign error. The answer stating the mean does not change assumes removing symmetric extremes always preserves the mean. The answer $\\frac{7}{4}$ results from an arithmetic error in the subtraction of fractions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O7OYCI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 40 students, 23 play soccer and 19 play basketball. If a student is chosen at random and the probability that the student plays neither sport is \\(\\dfrac{1}{10}\\), what is the probability that a randomly selected student plays both soccer and basketball?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{3}{20}\\)"},{"key":"B","text":"\\(\\dfrac{1}{4}\\)"},{"key":"C","text":"\\(\\dfrac{3}{40}\\)"},{"key":"D","text":"\\(\\dfrac{1}{5}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Let \\(b\\) be the number who play both. By the inclusion-exclusion principle, the number who play at least one sport is \\(23 + 19 - b = 42 - b\\). The number who play neither is \\(40 - (42 - b) = b - 2\\). Since the probability of playing neither is \\(\\dfrac{1}{10}\\), we have \\(\\dfrac{b - 2}{40} = \\dfrac{1}{10}\\), giving \\(b - 2 = 4\\) and \\(b = 6\\). The probability is \\(\\dfrac{6}{40} = \\dfrac{3}{20}\\). The answer \\(\\dfrac{1}{4}\\) results from setting \\(23 + 19 - b = 40\\) without accounting for the neither group. The answer \\(\\dfrac{3}{40}\\) comes from an arithmetic error of computing \\(b = 3\\) instead of \\(b = 6\\). The answer \\(\\dfrac{1}{5}\\) results from using \\(b = 8\\), likely by incorrectly solving \\(\\dfrac{b}{40} = \\dfrac{1}{10}\\) and doubling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PBGXGL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $4x - 9y = 63$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -7)$"},{"key":"B","text":"$(0, 7)$"},{"key":"C","text":"$(0, 63)$"},{"key":"D","text":"$\\left(\\frac{63}{4}, 0\\right)$"}]$lyceon_json$::jsonb, 'A', NULL, E'To find the $y$-intercept, set $x = 0$: $4(0) - 9y = 63$, so $-9y = 63$, giving $y = -7$. The $y$-intercept is $(0, -7)$. The answer $(0, 7)$ results from dropping the negative sign when dividing $63$ by $-9$. The answer $(0, 63)$ mistakes the constant on the right side for the $y$-intercept without dividing by the coefficient. The answer $\\left(\\frac{63}{4}, 0\\right)$ is the $x$-intercept, not the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PYZQ3G', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function \\(f\\) is defined by \\(f(x) = (x - 3)^2 + 5\\). Which of the following correctly describes the vertex and direction of opening of the graph of \\(f\\)?', NULL, $lyceon_json$[{"key":"A","text":"Vertex at \\((3, 5)\\), opens upward"},{"key":"B","text":"Vertex at \\((-3, 5)\\), opens upward"},{"key":"C","text":"Vertex at \\((3, -5)\\), opens upward"},{"key":"D","text":"Vertex at \\((3, 5)\\), opens downward"}]$lyceon_json$::jsonb, 'A', NULL, E'The function \\(f(x) = (x - 3)^2 + 5\\) is in vertex form \\(a(x - h)^2 + k\\) with \\(h = 3\\), \\(k = 5\\), and \\(a = 1 > 0\\). The vertex is at \\((3, 5)\\) and the parabola opens upward. The distractor with vertex \\((-3, 5)\\) results from taking the sign of the constant inside the parentheses directly, confusing \\(x - 3\\) with \\(h = -3\\). The distractor with vertex \\((3, -5)\\) applies a sign error to the vertical shift. The distractor claiming the parabola opens downward misidentifies the sign of the leading coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
