INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QFXO4P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles of a triangle measure $47°$ and $68°$. What is the measure, in degrees, of the third angle?', NULL, $lyceon_json$[{"key":"A","text":"$21°$"},{"key":"B","text":"$65°$"},{"key":"C","text":"$75°$"},{"key":"D","text":"$115°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180°$. The third angle is $180° - 47° - 68° = 65°$. The answer $21°$ results from subtracting the two given angles from each other ($68° - 47°$) instead of using the angle-sum property. The answer $75°$ results from an arithmetic error when subtracting ($180° - 47° - 68°$ miscalculated as $75°$ instead of $65°$). The answer $115°$ is the sum of the two given angles ($47° + 68°$), which a student might mistakenly report instead of subtracting that sum from $180°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RK7NEW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A trapezoid has parallel bases of length $13$ and $19$ and a height of $8$. What is the area of the trapezoid?', NULL, $lyceon_json$[{"key":"A","text":"$104$"},{"key":"B","text":"$128$"},{"key":"C","text":"$152$"},{"key":"D","text":"$256$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a trapezoid is $A = \\frac{1}{2}(b_1 + b_2)h = \\frac{1}{2}(13 + 19)(8) = \\frac{1}{2}(32)(8) = 128$. The value $104$ results from using only the shorter base ($13 \\times 8 = 104$), ignoring the other base entirely. The value $152$ results from using only the longer base ($19 \\times 8 = 152$) without averaging the two bases. The value $256$ comes from computing $(13 + 19)(8) = 256$ but omitting the factor of $\\frac{1}{2}$ in the trapezoid area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TJY6K3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health clinic observes that patients who attend weekly yoga classes report lower stress levels than patients who do not attend yoga classes. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Attending yoga classes causes lower stress levels."},{"key":"B","text":"There is an association between attending yoga classes and lower reported stress levels."},{"key":"C","text":"Patients who do not attend yoga classes will always have high stress levels."},{"key":"D","text":"Yoga is the most effective treatment for stress reduction."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study — patients self-selected into yoga classes — the result can only establish an association, not a causal relationship. The claim that yoga causes lower stress is unsupported because participants were not randomly assigned, so confounding variables (e.g., those who attend yoga may have more leisure time or healthier lifestyles overall) cannot be ruled out. The claim that non-yoga patients will always have high stress is an absolute statement unsupported by an association. The claim that yoga is the most effective treatment goes far beyond the study''s scope, which did not compare yoga to other treatments.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TXP5SD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces $11$ pages every $2$ minutes. At this rate, how many pages does the printer produce in $18$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"88"},{"key":"B","text":"90"},{"key":"C","text":"96"},{"key":"D","text":"99"}]$lyceon_json$::jsonb, 'D', NULL, E'The rate is $11/2 = 5.5$ pages per minute. In 18 minutes: $5.5 \\times 18 = 99$ pages.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UN4SM5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ lies on $\\overline{AB}$ and point $E$ lies on $\\overline{AC}$ such that $\\overline{DE} \\parallel \\overline{BC}$. If $AD = 7$, $DB = 4$, $AE = 2x + 1$, and $EC = x + 2$, what is the value of $\\frac{DE}{BC}$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/11', ARRAY['7/11', '0.636', '.636'], E'Since $\\overline{DE} \\parallel \\overline{BC}$, by the basic proportionality theorem (or similar triangles), $\\frac{AD}{DB} = \\frac{AE}{EC}$. Setting up the proportion: $\\frac{7}{4} = \\frac{2x + 1}{x + 2}$. Cross-multiplying gives $7(x + 2) = 4(2x + 1)$, which simplifies to $7x + 14 = 8x + 4$, so $x = 10$. This means $AE = 21$ and $EC = 12$, confirming $\\frac{AE}{EC} = \\frac{21}{12} = \\frac{7}{4}$. Since $\\triangle ADE \\sim \\triangle ABC$ with ratio $\\frac{AD}{AB} = \\frac{7}{7 + 4} = \\frac{7}{11}$, corresponding sides are proportional, so $\\frac{DE}{BC} = \\frac{7}{11}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V2FLOE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers randomly assign 120 participants to one of two groups. Group A receives a new herbal supplement daily for 8 weeks, while Group B receives an identical-looking placebo. At the end of the study, Group A shows a statistically significant improvement in sleep quality compared to Group B. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The herbal supplement is likely to improve sleep quality in the general population."},{"key":"B","text":"The herbal supplement caused an improvement in sleep quality among the participants."},{"key":"C","text":"The herbal supplement is associated with but did not necessarily cause improved sleep quality."},{"key":"D","text":"The improvement in sleep quality was due to the placebo effect experienced by Group A."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants were randomly assigned to treatment and control groups and a placebo was used, this is a well-designed experiment. Random assignment allows a causal conclusion about the effect of the supplement on these participants. The claim about the general population goes beyond the study because the participants may not be representative of the broader population — generalizability requires random selection from the population, not just random assignment within the study. The claim that the supplement is only associated with improved sleep incorrectly applies the observational-study limitation to a randomized experiment. The claim that the improvement was due to the placebo effect ignores that Group B received the placebo, so any placebo effect would appear in Group B, not Group A.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VH05C1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 400 adults in a county and finds that 37% exercise at least three times per week, with a margin of error of 3.1 percentage points at the 95% confidence level. The county has 52,000 adults. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"Between 17,628 and 20,852 adults in the county exercise at least three times per week."},{"key":"B","text":"Exactly 19,240 adults in the county exercise at least three times per week."},{"key":"C","text":"Between 33.9% and 40.1% of all adults in the country exercise at least three times per week."},{"key":"D","text":"If the sample size were increased to 800, the margin of error would be 1.55 percentage points."}]$lyceon_json$::jsonb, 'A', NULL, E'The confidence interval is \\(37\\% \\pm 3.1\\%\\), or 33.9% to 40.1%, applied to the county population of 52,000. This gives \\(0.339 \\times 52{,}000 = 17{,}628\\) to \\(0.401 \\times 52{,}000 = 20{,}852\\). The claim of exactly 19,240 adults treats the sample proportion as exact rather than an estimate. The answer referencing "the country" incorrectly generalizes beyond the county population that was sampled. The claim that doubling the sample size halves the margin of error is incorrect because the margin of error is proportional to \\(\\dfrac{1}{\\sqrt{n}}\\), so doubling \\(n\\) reduces it by a factor of \\(\\sqrt{2}\\), not 2.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W0W79P', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function \\(h\\) is defined by \\(h(x) = -2(x + 1)^3 + 16\\). For what value of \\(x\\) does \\(h(x) = 0\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(1\\)"},{"key":"B","text":"\\(-1\\)"},{"key":"C","text":"\\(3\\)"},{"key":"D","text":"\\(-3\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting \\(h(x) = 0\\): \\(-2(x + 1)^3 + 16 = 0\\). Subtracting 16 from both sides: \\(-2(x + 1)^3 = -16\\). Dividing by \\(-2\\): \\((x + 1)^3 = 8\\). Taking the cube root: \\(x + 1 = 2\\), so \\(x = 1\\). The distractor \\(-1\\) is the value that makes \\((x + 1) = 0\\) rather than solving the full equation for when the output is zero. The distractor \\(3\\) results from a sign error such as solving \\(x - 1 = 2\\) instead of \\(x + 1 = 2\\). The distractor \\(-3\\) comes from incorrectly computing the cube root of 8 as \\(-2\\), giving \\(x + 1 = -2\\) and \\(x = -3\\).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WDGNRL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 2y + 14 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$6$"},{"key":"C","text":"$14$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $(x^2 - 14x + 49) + (y^2 + 2y + 1) = -14 + 49 + 1$, which gives $(x - 7)^2 + (y + 1)^2 = 36$. Since the standard form is $(x - h)^2 + (y - k)^2 = r^2$, we have $r^2 = 36$ and $r = 6$. The value $3$ results from a computational error when completing the square, such as miscalculating $-14 + 49 + 1$ as $9$ instead of $36$, yielding $r = 3$. The value $14$ comes from taking the coefficient of $x$ as the diameter or radius without completing the square. The value $36$ is $r^2$ rather than $r$, forgetting to take the square root in the final step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WT6TLN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A water tank contains $185$ gallons and is being drained at a constant rate. After $7$ hours, the tank contains $87$ gallons. What is the rate of change, in gallons per hour, of the amount of water in the tank?', NULL, $lyceon_json$[{"key":"A","text":"$-14$"},{"key":"B","text":"$14$"},{"key":"C","text":"$-\\frac{87}{7}$"},{"key":"D","text":"$-98$"}]$lyceon_json$::jsonb, 'A', NULL, E'The rate of change is $\\frac{87 - 185}{7 - 0} = \\frac{-98}{7} = -14$ gallons per hour. The value $14$ has the correct magnitude but drops the negative sign, ignoring that the tank is draining. The value $-\\frac{87}{7}$ uses only the final amount divided by time rather than computing the change in water level. The value $-98$ gives the total change in gallons but does not divide by the elapsed time to find the hourly rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X0F1SW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A researcher collects data on $x$ (hours of sunlight per day) and $y$ (plant height in centimeters after $30$ days). The line of best fit is $y = 3.7x - 4.1$. One data point has $x = 9$ and an actual $y$-value of $27.2$. What is the residual for this data point?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'The predicted value from the line of best fit when $x = 9$ is $y = 3.7(9) - 4.1 = 33.3 - 4.1 = 29.2$. The residual is the actual value minus the predicted value: $27.2 - 29.2 = -2$. A negative residual means the actual value is below the line of best fit. A common error is computing the residual as predicted minus actual, which gives $2$ instead of $-2$, or making an arithmetic error in evaluating the linear expression.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XQW8GO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{5(x - 3)}{2} = \\frac{3x + 7}{4}$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{7}$"},{"key":"B","text":"$\\frac{17}{7}$"},{"key":"C","text":"$\\frac{37}{7}$"},{"key":"D","text":"$\\frac{44}{7}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Cross-multiply: $4 \\cdot 5(x-3) = 2(3x+7)$, so $20x - 60 = 6x + 14$. Then $14x = 74$, giving $x = 37/7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YXJ601', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $\\sqrt{11}$ and $\\sqrt{14}$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{3}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$25$"},{"key":"D","text":"$\\sqrt{154}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, the hypotenuse $c$ satisfies $c^2 = (\\sqrt{11})^2 + (\\sqrt{14})^2 = 11 + 14 = 25$, so $c = \\sqrt{25} = 5$. The value $\\sqrt{3}$ results from subtracting the squares ($14 - 11 = 3$) instead of adding them. The value $25$ comes from correctly computing $c^2 = 25$ but forgetting to take the square root. The value $\\sqrt{154}$ results from multiplying the leg lengths ($\\sqrt{11} \\cdot \\sqrt{14} = \\sqrt{154}$) instead of summing their squares.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZPW8N2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A paint mixture requires $3$ parts blue to $11$ parts white. If a painter uses $5.5$ gallons of white paint, how many gallons of blue paint should the painter use?', NULL, $lyceon_json$[{"key":"A","text":"$1.0$"},{"key":"B","text":"$1.5$"},{"key":"C","text":"$2.0$"},{"key":"D","text":"$3.0$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio of blue to white is $3:11$. Setting up the proportion: $\\frac{3}{11} = \\frac{x}{5.5}$. Solving: $x = \\frac{3 \\times 5.5}{11} = \\frac{16.5}{11} = 1.5$ gallons. The answer $1.0$ results from incorrectly dividing $5.5$ by $5.5$ or using the wrong ratio. The answer $2.0$ comes from a rounding or arithmetic error in cross-multiplication. The answer $3.0$ assumes the blue amount equals the ratio numerator directly, ignoring the proportion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZYBRD5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'For what positive value of \\(k\\) does the equation \\(3x^2 + kx + 27 = 0\\) have exactly one real solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'A quadratic equation \\(ax^2 + bx + c = 0\\) has exactly one real solution when its discriminant equals zero: \\(b^2 - 4ac = 0\\). Here \\(a = 3\\), \\(b = k\\), and \\(c = 27\\). Setting the discriminant to zero: \\(k^2 - 4(3)(27) = 0\\), so \\(k^2 = 324\\), giving \\(k = \\pm 18\\). The positive value is \\(18\\). A common error is computing \\(4 \\times 3 \\times 27\\) incorrectly or forgetting to take the square root of 324.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZZ0R6N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 150 voters in a city found that 57% support a new library proposal. The margin of error is 4 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 57% of all voters in the city support the proposal."},{"key":"B","text":"Between 53% and 61% of all voters in the city are plausibly supportive of the proposal."},{"key":"C","text":"Between 53% and 61% of the 150 sampled voters support the proposal."},{"key":"D","text":"If another sample were taken, exactly 57% would again support the proposal."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of 4 percentage points means the plausible range for the true population proportion is \\(57\\% \\pm 4\\%\\), or between 53% and 61%. This interval applies to all voters in the city, not just the sample. The claim that exactly 57% of all voters support the proposal treats the sample statistic as the exact population parameter. The claim about 53% to 61% of the sampled voters misapplies the interval to the sample rather than the population. The claim that another sample would yield exactly 57% ignores sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW207H11R', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Priya Venkatesh has argued that the ceramic styles found at the Sangam-era site of Arikamedu reflect sustained trade networks between southern India and the Roman Empire. Her analysis of pottery fragments reveals close similarities to terra sigillata, a distinctly Roman style of red-glazed tableware. _______ some scholars contend that these resemblances are superficial and that the Arikamedu ceramics developed independently through parallel innovation rather than cultural exchange.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"However,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first presents Venkatesh''s argument that pottery similarities indicate trade between southern India and Rome. The sentence after the blank introduces opposing scholars who believe the resemblances are superficial and arose independently. "However," correctly signals this contrast between Venkatesh''s position and the dissenting view. "Furthermore," incorrectly suggests that the opposing scholars'' claim adds to Venkatesh''s argument, when it actually challenges it. "Consequently," wrongly implies that the independent-innovation argument is a logical result of Venkatesh''s findings, but it is a rebuttal, not a consequence. "Similarly," falsely suggests the dissenting scholars agree with Venkatesh, when they propose a fundamentally different explanation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22X7W5L', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geophysicist Lena Thorvaldsen has proposed that the unusually low seismic activity along the Tjörnes Fracture Zone in northern Iceland is not evidence of geological stability but rather an indication that tectonic stress is accumulating silently. She points to GPS measurements showing that crustal deformation in the region has accelerated by 17 percent over the past decade, despite the absence of significant earthquakes. _______ Thorvaldsen warns that this pattern closely mirrors the precursory phase observed before the 2000 South Iceland sequence, during which a comparable period of quiescence preceded two magnitude-6.5 earthquakes within four days.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"To that end,"},{"key":"D","text":"On this basis,"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence before the blank presents Thorvaldsen''s GPS evidence of accelerating crustal deformation. The sentence after the blank draws a conclusion from that evidence: the current pattern mirrors a known precursory phase. "On this basis," correctly signals that the warning is grounded in the preceding evidence. "In other words," suggests a restatement of the same idea, but Thorvaldsen is not restating the GPS data — she is using it as the foundation for a new predictive claim about seismic risk. "In contrast," incorrectly implies an opposition between the GPS findings and the warning, when the warning actually follows from the findings. "To that end," implies that the warning is a purposeful action taken to achieve the goal stated in the preceding sentence, but the preceding sentence presents evidence, not a goal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW242N61E', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken Menon''s argument?', E'Economist Radhika Menon has proposed that increases in remote work adoption after 2020 disproportionately benefited workers in mid-sized cities (populations between 100,000 and 500,000) by expanding their access to jobs previously concentrated in major metropolitan areas. Menon argues that this shift reduced wage disparities between mid-sized and large cities for knowledge-sector employees.', $lyceon_json$[{"key":"A","text":"Between 2020 and 2024, median wages for remote knowledge-sector workers in mid-sized cities remained 23 percent below those of comparable workers in cities with populations exceeding one million."},{"key":"B","text":"The number of coworking spaces in mid-sized cities increased by 40 percent between 2020 and 2024."},{"key":"C","text":"Workers in manufacturing sectors, which generally cannot be performed remotely, experienced wage stagnation across cities of all sizes."},{"key":"D","text":"Several large technology companies established satellite offices in mid-sized cities during the same period, hiring locally at metropolitan-level salaries."}]$lyceon_json$::jsonb, 'A', NULL, E'Menon argues that remote work reduced wage disparities between mid-sized and large cities for knowledge-sector workers. A finding that median wages for remote knowledge-sector workers in mid-sized cities remained 23 percent below those in large cities directly contradicts the claim that the gap narrowed. The growth of coworking spaces indicates infrastructure change but says nothing about whether wages converged. The stagnation of manufacturing wages is irrelevant because Menon''s argument specifically concerns knowledge-sector employees who can work remotely. The establishment of satellite offices paying metropolitan salaries could actually support Menon''s general point about mid-sized-city workers gaining access to higher wages, rather than weakening it; moreover, it describes in-person hiring rather than remote work effects.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24IV05H', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the two texts characterize the role of urban green spaces?', E'Text 1: City planner Dario Fabbri argues that urban green spaces serve primarily as psychological refuges. In a 2021 survey of 3,400 residents across seven Italian cities, Fabbri found that respondents who lived within 500 meters of a park reported significantly lower levels of perceived stress and higher life satisfaction, regardless of whether they physically visited the park. Fabbri concludes that the mere proximity to green space — its visibility from windows, its presence on daily walking routes — generates a calming cognitive frame that measurably benefits mental health.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24XXT6G', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best captures how the passage presents the debate over rewilding?', E'The concept of ''rewilding''—restoring ecosystems by reintroducing species that have been locally extirpated—has gained traction among conservation biologists since the 1990s. Proponents point to the reintroduction of gray wolves to Yellowstone National Park in 1995 as a landmark success: the wolves'' predation on elk triggered a trophic cascade that allowed overgrazed riparian vegetation to recover, stabilizing stream banks and increasing habitat for songbirds, beavers, and fish. Critics, however, contend that the Yellowstone case is frequently oversimplified. Ecologist Marco Ferretti has argued that concurrent changes in climate, park management policies, and natural elk population fluctuations contributed substantially to the vegetation recovery, making it misleading to attribute the cascade primarily to wolf reintroduction. Ferretti does not oppose rewilding categorically but insists that conservation strategies must account for the full complexity of ecosystem dynamics rather than relying on narratives centered on a single charismatic species.', $lyceon_json$[{"key":"A","text":"It contrasts a widely cited example of rewilding success with a critique that the example overlooks contributing ecological factors."},{"key":"B","text":"It argues that rewilding is fundamentally flawed because trophic cascades depend on too many variables to predict."},{"key":"C","text":"It presents two irreconcilable positions on wolf reintroduction and concludes that neither side has sufficient evidence."},{"key":"D","text":"It endorses the Yellowstone rewilding project while acknowledging that similar projects in other locations have failed."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first presents the proponents'' view of the Yellowstone wolf reintroduction as a rewilding success, then introduces Ferretti''s critique that other factors contributed to the vegetation recovery. The choice describing a contrast between a widely cited success and a critique about overlooked factors accurately captures this structure. The claim that rewilding is fundamentally flawed overstates Ferretti''s position—the passage notes he ''does not oppose rewilding categorically.'' The characterization of two irreconcilable positions misrepresents the debate, since Ferretti''s objection is about oversimplification, not about opposing rewilding entirely, and the passage does not judge evidentiary sufficiency. The suggestion that the passage endorses Yellowstone while noting failures elsewhere is inaccurate—the passage never mentions other rewilding projects or endorse the Yellowstone case.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26ZUAGJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'When the city of Arvika, Sweden, converted its downtown streetlights from high-pressure sodium lamps to LED fixtures in 2021, municipal engineers expected electricity consumption for street lighting to drop by approximately 45 percent. After two full years of operation, however, the measured reduction was only 29 percent. An internal review found that the new LED fixtures had been installed at a higher density than the old sodium lamps—one fixture every 18 meters instead of every 31 meters—because the LED units produced a narrower beam angle and the city''s lighting ordinance required uniform illumination across the full width of each street.', $lyceon_json$[{"key":"A","text":"The LED conversion failed to meet its projected savings because the narrower beam angle of the new fixtures required more units to satisfy existing illumination standards."},{"key":"B","text":"Arvika's lighting ordinance was revised after the conversion to allow lower illumination levels on residential streets."},{"key":"C","text":"The high-pressure sodium lamps consumed less electricity per unit than initially estimated by the municipal engineers."},{"key":"D","text":"LED technology is generally unsuitable for street lighting applications in northern European climates."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that the LED fixtures had narrower beam angles, requiring higher installation density to meet the city''s uniform-illumination ordinance, which offset some of the expected energy savings. The conclusion that the savings shortfall resulted from needing more fixtures to satisfy illumination standards follows directly from the stated facts. The claim that the ordinance was revised is unsupported—the passage gives no indication the standards were changed. The suggestion that sodium lamps consumed less than estimated contradicts the passage''s framing, which attributes the shortfall to the number of LED fixtures, not to miscalculating sodium lamp consumption. The sweeping claim that LED technology is unsuitable for northern European street lighting goes far beyond anything the passage supports.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW286DUO0', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists studying the behavior of giant Pacific octopuses in Puget Sound have documented the animals'' remarkable capacity for camouflage. The octopuses can alter not only their skin color but also its texture, matching the coral, kelp, and rocky surfaces of their environment within milliseconds. _______ the speed and precision of these transformations have led researchers to hypothesize that the octopuses possess a distributed visual system embedded in their skin cells.', $lyceon_json$[{"key":"A","text":"Indeed,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Alternatively,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes the octopuses'' impressive camouflage abilities, and the sentence following the blank intensifies this point by noting that the speed and precision of these transformations have inspired a specific hypothesis. The transitional word "Indeed," correctly signals that the next sentence reinforces and extends the preceding claim. "Nevertheless," incorrectly introduces a contrast where none exists, since the hypothesis about a distributed visual system supports rather than contradicts the preceding description. "Alternatively," wrongly implies a competing explanation is being offered, but the sentence presents a consequence, not an alternative. "Meanwhile," inaccurately suggests a shift to a simultaneous but separate event, whereas the sentence continues the same line of reasoning about camouflage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28AGAPC', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During the 1970s, biochemist Toshiko ______ a staining protocol that later became standard in electron microscopy laboratories worldwide.', $lyceon_json$[{"key":"A","text":"Fukuda, whose research on mitochondrial membrane permeability was largely overlooked at the time, developed"},{"key":"B","text":"Fukuda, whose research on mitochondrial membrane permeability was largely overlooked at the time developed"},{"key":"C","text":"Fukuda whose research on mitochondrial membrane permeability was largely overlooked at the time, developed"},{"key":"D","text":"Fukuda whose research on mitochondrial membrane permeability was largely overlooked at the time developed"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause "whose research on mitochondrial membrane permeability was largely overlooked at the time" is a nonrestrictive relative clause modifying the proper noun "Toshiko Fukuda." Because the person is already fully identified by name, the clause provides supplementary rather than essential information and must be set off by a pair of commas — one before "whose" and one after "time." Omitting the closing comma after "time" leaves the nonrestrictive clause unpaired, disrupting the sentence boundary. Omitting the opening comma before "whose" incorrectly treats the clause as restrictive, implying there are multiple Toshiko Fukudas and this clause identifies which one. Omitting both commas compounds that error by removing all punctuation around a nonrestrictive element.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CTQ8H9', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Voynich Manuscript, a fifteenth-century codex written in an undeciphered script, has baffled cryptographers for ______ some scholars argue that the text is not a cipher at all but rather an invented language with no underlying meaning.', $lyceon_json$[{"key":"A","text":"decades, some"},{"key":"B","text":"decades; some"},{"key":"C","text":"decades some"},{"key":"D","text":"decades and some"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses appear here: one stating that the manuscript has baffled cryptographers and another presenting certain scholars'' counterargument. A semicolon correctly joins these closely related independent clauses. A comma alone after "decades" produces a comma splice. Omitting all punctuation after "decades" creates a run-on sentence. Using "and" without a comma creates a faulty compound predicate, since "has baffled" is singular (the manuscript) while "argue" is plural (some scholars), so they cannot share a compound predicate joined by a simple "and."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DF9JKE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Volcanic glass, known as obsidian, forms when lava cools so rapidly that atoms cannot arrange themselves into a crystalline structure. Ancient peoples across the Americas valued obsidian for toolmaking because its conchoidal fracture pattern produces edges sharper than modern surgical steel. [underlined] Archaeological sites in central Mexico have yielded obsidian blades dating to 7000 BCE. [/underlined] These discoveries demonstrate that sophisticated stone-knapping techniques existed millennia before the rise of the region''s first major civilizations.', $lyceon_json$[{"key":"A","text":"It provides specific evidence supporting the claim that obsidian was used for toolmaking in ancient times."},{"key":"B","text":"It challenges a previous assumption about the geographic origins of obsidian."},{"key":"C","text":"It explains the chemical process by which obsidian forms from molten rock."},{"key":"D","text":"It introduces a comparison between ancient and modern cutting instruments."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence cites archaeological evidence from central Mexico (obsidian blades dating to 7000 BCE), which directly supports the preceding claim about ancient peoples using obsidian for toolmaking. The option stating it provides specific evidence supporting the toolmaking claim correctly identifies this function. The option about challenging geographic origins is wrong because the sentence introduces a location to support toolmaking, not to dispute where obsidian originates. The option about explaining chemical formation is wrong because the formation process is described in the first sentence, not the underlined one. The option about comparing ancient and modern cutting instruments misidentifies the function: the comparison to surgical steel appears earlier in the passage and is not the purpose of the underlined sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EMC1PP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'For decades, ecologists assumed that forest fires were purely destructive events that ecosystems needed to recover from. However, research conducted in the lodgepole pine forests of Yellowstone after the 1988 fires revealed a more complex picture. Certain plant species, such as fireweed and lupine, colonize burned areas within weeks, stabilizing soil and cycling nutrients back into the ground. Meanwhile, the newly opened canopy allows sunlight to reach the forest floor, triggering germination of seeds that had lain dormant for years. These findings have led many ecologists to reconceive fire not as an ecological catastrophe but as a periodic renewal mechanism integral to forest health.', $lyceon_json$[{"key":"A","text":"It presents a traditional view, introduces evidence that complicates that view, and then describes a revised understanding."},{"key":"B","text":"It proposes a hypothesis, lists exceptions to it, and then dismisses the hypothesis entirely."},{"key":"C","text":"It describes a natural process, compares two competing explanations, and then identifies which explanation is more widely accepted."},{"key":"D","text":"It narrates a historical event, evaluates its long-term consequences, and then predicts future occurrences."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first presents the traditional assumption (fires are purely destructive), then introduces post-1988 research showing that fire promotes rapid plant colonization and seed germination, and finally describes the revised understanding (fire as a renewal mechanism). The option describing this three-part structure -- traditional view, complicating evidence, revised understanding -- accurately captures the text''s organization. The option about proposing and dismissing a hypothesis overstates the conclusion: the text says ecologists reconceived fire''s role, not that the original view was entirely dismissed. The option about comparing two competing explanations is inaccurate because the text does not present two parallel explanations for evaluation; it traces a shift from one view to another. The option about narrating a historical event and predicting the future is wrong because the text does not make predictions about future fires.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FI7FTB', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely respond to the conclusion presented in Text 2?', E'Text 1: Cognitive scientist Miriam Okafor has proposed that bilingual individuals do not possess a generalized cognitive advantage over monolinguals. After conducting a meta-analysis of 146 studies spanning three decades, Okafor found that when researchers controlled for socioeconomic status, immigration history, and educational attainment, the so-called "bilingual advantage" in executive function tasks — such as task-switching and inhibitory control — shrank to a statistically negligible effect size. Okafor argues that earlier findings were inflated by publication bias and confounding demographic variables.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GCAJRO', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists have long studied the Atlantic horseshoe crab, whose ancestry can be traced back over 450 million years. Despite dramatic shifts in ocean chemistry, temperature, and predator populations, the species has __________ remarkably little, retaining the same basic body plan found in its earliest fossil ancestors.', $lyceon_json$[{"key":"A","text":"changed"},{"key":"B","text":"competed"},{"key":"C","text":"dispersed"},{"key":"D","text":"consumed"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a species that has retained the same body plan for 450 million years despite environmental shifts, so the blank must convey that the species has altered or transformed very little. "Changed" fits this meaning precisely: the horseshoe crab has changed remarkably little over time. "Competed" refers to rivalry for resources, which does not logically complete the idea of retaining the same body plan. "Dispersed" means scattered or spread out geographically, which is unrelated to maintaining a consistent physical form. "Consumed" means eaten or used up, which has no coherent connection to the passage''s point about morphological stability.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GCZ4IW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice describes an inference about late bilinguals that is most strongly supported by Chakrabarti''s findings as presented in the passage?', E'Neuroscientist Priya Chakrabarti has studied how bilingual individuals process grammatical errors in their second language. In a 2023 experiment, Chakrabarti presented 54 Mandarin-English bilinguals with English sentences containing subject-verb agreement errors (e.g., ''The engineers designs the bridge'') and measured event-related potentials (ERPs) using electroencephalography. Participants who had acquired English before age seven showed a robust P600 response—a brain signal associated with syntactic reanalysis—comparable to that of monolingual English speakers. Participants who had acquired English after age thirteen showed a significantly attenuated P600 but exhibited an enhanced N400 response, a signal typically associated with semantic rather than syntactic processing. Chakrabarti interprets this pattern as evidence that late bilinguals may recruit semantic processing pathways to compensate for less automatic syntactic processing in their second language.', $lyceon_json$[{"key":"A","text":"They detect grammatical errors in their second language through a processing mechanism that differs from the one used by early bilinguals and monolinguals."},{"key":"B","text":"They are unable to identify subject-verb agreement errors in their second language without explicit grammatical instruction."},{"key":"C","text":"They process syntactic and semantic information in their second language using the same neural pathways as in their first language."},{"key":"D","text":"They would show a P600 response comparable to early bilinguals if given sufficient practice with English grammatical structures."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that late bilinguals showed an attenuated P600 (syntactic signal) but enhanced N400 (semantic signal), while early bilinguals and monolinguals showed a robust P600. Chakrabarti interprets this as late bilinguals recruiting semantic pathways to compensate for less automatic syntactic processing. The inference that late bilinguals detect errors through a different processing mechanism than early bilinguals and monolinguals is directly supported. The claim that late bilinguals cannot identify errors without instruction goes beyond the evidence—the passage shows they do process the errors, just through different neural pathways. The assertion about same neural pathways as the first language is unsupported because the study did not compare processing in participants'' first language. The prediction that practice would produce comparable P600 responses is speculative—the passage presents no evidence about whether increased exposure alters these ERP patterns.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HEAHBU', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most effectively support Okafor''s hypothesis while simultaneously undermining the coevolution hypothesis?', E'Paleobotanist Idris Okafor has challenged the prevailing view that the diversification of flowering plants (angiosperms) in the late Cretaceous period was driven primarily by coevolution with insect pollinators. Okafor''s alternative hypothesis holds that the key driver was angiosperms'' superior ability to colonize disturbed habitats—areas cleared by volcanic eruptions, flooding, or dinosaur activity—compared to the gymnosperms and ferns that previously dominated those niches. According to Okafor, angiosperms'' rapid growth rates and short generation times gave them a decisive advantage in recolonizing bare ground, allowing them to establish dominance before slower-growing competitors could recover.', $lyceon_json$[{"key":"A","text":"Fossil evidence from late Cretaceous sites shows that the earliest angiosperm-dominated communities appeared in volcanic ashfall zones and contained predominantly wind-pollinated species with no specialized insect-pollination structures."},{"key":"B","text":"Genetic analyses reveal that the ancestors of modern bee families diverged into multiple lineages during the same period as the angiosperm radiation."},{"key":"C","text":"Fossilized angiosperm pollen from the late Cretaceous has been found on every continent, indicating a global distribution pattern."},{"key":"D","text":"Some modern gymnosperms, such as certain cycad species, rely exclusively on beetle pollinators for reproduction."}]$lyceon_json$::jsonb, 'A', NULL, E'The stem asks for evidence that supports disturbance-colonization while undermining insect coevolution. The finding that early angiosperm communities appeared in volcanic ashfall zones (supporting disturbance colonization) and were predominantly wind-pollinated with no specialized insect structures (undermining insect coevolution) accomplishes both requirements simultaneously. The bee-lineage divergence finding would support the coevolution hypothesis rather than undermine it, since it suggests insect diversification coincided with angiosperm radiation. The global pollen distribution shows angiosperms spread widely but does not distinguish between the two competing explanations for why they diversified. The fact that some modern gymnosperms use beetle pollinators concerns present-day gymnosperms, not Cretaceous angiosperms, and does not address the disturbance-colonization mechanism at all.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HR3IFH', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the conservation team arrived at the high-altitude glacier site in the Karakoram Range, unseasonable warmth ______ much of the exposed ice surface into meltwater pools, leaving the researchers with fewer viable extraction points than their initial survey had projected.', $lyceon_json$[{"key":"A","text":"had already transformed"},{"key":"B","text":"has already transformed"},{"key":"C","text":"already transformed"},{"key":"D","text":"would already transform"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction "by the time [past event]" signals that another action was completed before that past event, requiring the past perfect tense. "Had already transformed" correctly indicates that the warmth''s effect on the ice occurred before the team''s arrival. The present perfect "has already transformed" is wrong because the entire narrative is set in the past. The simple past "already transformed" fails to convey the sequence of completion before another past event that "by the time" demands. The conditional "would already transform" implies a hypothetical scenario, which contradicts the passage''s factual narration of events that actually occurred.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J94YPK', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to present azolla as a practical alternative to synthetic fertilizer for an audience unfamiliar with the plant. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a report on sustainable agriculture, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JNC63I', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the passage, what is the primary factor that food historians identify as driving the development of Hawaiian plantation cuisine?', E'In the early twentieth century, the Hawaiian sugar industry relied heavily on imported labor from Japan, the Philippines, and Portugal. Each group brought distinct culinary traditions, and the close quarters of plantation camps fostered an unprecedented exchange of cooking techniques and ingredients. Japanese workers introduced shoyu and rice as staples; Filipino laborers contributed adobo-style braising methods; Portuguese immigrants brought sweet bread and bean soup. Over decades, these traditions merged into a distinctive local cuisine that cannot be attributed to any single origin culture. Food historians argue that this fusion was not a deliberate cultural project but an organic adaptation driven by proximity, shared economic hardship, and limited ingredient availability.', $lyceon_json$[{"key":"A","text":"A coordinated effort among plantation workers to create a unified cultural identity through food"},{"key":"B","text":"The practical circumstances of living and working in close proximity with limited resources"},{"key":"C","text":"The dominance of Japanese culinary traditions over those of Filipino and Portuguese workers"},{"key":"D","text":"The plantation owners' deliberate policy of encouraging cultural exchange among workers"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that the fusion was ''not a deliberate cultural project but an organic adaptation driven by proximity, shared economic hardship, and limited ingredient availability.'' The choice identifying practical circumstances of proximity and limited resources directly reflects this. The coordinated-effort option contradicts the passage''s explicit statement that the fusion was not deliberate. The claim of Japanese dominance is unsupported—the passage presents all three groups'' contributions without ranking them. The plantation-owner-policy option introduces an actor and motive not mentioned anywhere in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LH1W3R', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to acknowledge a current limitation of synthetic spider silk while conveying optimism about its commercial future. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a presentation on materials science, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O1MH0I', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support Takahashi''s hypothesis?', E'Marine biologist Yuna Takahashi hypothesizes that deep-sea octopuses in the genus Graneledone regulate their metabolic rates in response to seasonal fluctuations in food availability near hydrothermal vents. During periods of reduced vent activity, these octopuses enter a torpor-like state, lowering their oxygen consumption by as much as 60 percent compared to active feeding periods.', $lyceon_json$[{"key":"A","text":"Graneledone octopuses observed near inactive vents displayed oxygen consumption rates 58 percent lower than those observed near active vents during peak output."},{"key":"B","text":"Several species of deep-sea fish near hydrothermal vents show no measurable change in metabolic rate regardless of vent activity levels."},{"key":"C","text":"Graneledone octopuses have been found at depths exceeding 4,000 meters, farther from hydrothermal vents than previously documented."},{"key":"D","text":"Laboratory studies indicate that shallow-water octopus species can survive brief periods of food deprivation without significant metabolic changes."}]$lyceon_json$::jsonb, 'A', NULL, E'Takahashi''s hypothesis proposes that Graneledone octopuses reduce their metabolic rates when food availability declines due to reduced vent activity. A finding that these octopuses near inactive vents showed oxygen consumption 58 percent lower than those near active vents directly supports this claim by demonstrating the predicted metabolic reduction under the predicted conditions. The finding about deep-sea fish showing no metabolic change concerns a different taxon and does not bear on octopus metabolism. The observation about Graneledone at greater depths addresses geographic range, not metabolic regulation. The laboratory study of shallow-water octopus species involves different organisms in different conditions and cannot confirm a hypothesis about deep-sea species near hydrothermal vents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PLWQK6', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to emphasize the surprising extent of the peregrine falcon''s urban recovery. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a presentation on urban wildlife adaptation, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QDFJ5H', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the passage, which choice most logically follows from Dessalines''s argument?', E'Historian Camille Dessalines has examined the correspondence of nineteenth-century Haitian coffee growers who exported their crops to European markets. Dessalines notes that these growers frequently adjusted their processing methods—switching between washed and natural drying techniques—based not on local agricultural conditions but on feedback from French and German commodity brokers about European consumer preferences. When brokers reported that buyers favored a cleaner, brighter cup profile, growers invested in washing stations; when the market shifted toward earthier, fuller-bodied coffees, growers reverted to natural processing. Dessalines argues that this pattern complicates the conventional narrative, which portrays nineteenth-century Haitian agriculture as isolated from global market signals.', $lyceon_json$[{"key":"A","text":"Nineteenth-century Haitian coffee growers were more responsive to international market dynamics than traditional historical accounts have suggested."},{"key":"B","text":"The quality of Haitian coffee declined during the nineteenth century because growers prioritized market trends over agricultural best practices."},{"key":"C","text":"European commodity brokers deliberately manipulated Haitian growers to keep coffee prices artificially low."},{"key":"D","text":"Washed processing consistently produces higher-quality coffee than natural drying regardless of consumer preferences."}]$lyceon_json$::jsonb, 'A', NULL, E'Dessalines argues that Haitian growers adjusted their methods based on European broker feedback, which ''complicates the conventional narrative'' of Haitian agriculture as ''isolated from global market signals.'' The inference that these growers were more responsive to international markets than traditional accounts suggest follows directly. The claim about declining coffee quality introduces a judgment about agricultural outcomes not discussed in the passage. The assertion that brokers deliberately manipulated growers imputes motives that the passage does not mention—brokers relayed consumer preferences, but no exploitation is described. The claim about washed processing being universally superior makes a quality judgment the passage does not support; the passage treats both methods as responses to different consumer preferences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R5Q0UU', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In a 2019 study of urban noise pollution, acoustics researcher Yuna Park found that prolonged exposure to low-frequency vibrations from subway systems could __________ residents'' sleep architecture, fragmenting deep-sleep cycles without necessarily waking the sleeper.', $lyceon_json$[{"key":"A","text":"disrupt"},{"key":"B","text":"abbreviate"},{"key":"C","text":"diagnose"},{"key":"D","text":"fabricate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes vibrations fragmenting deep-sleep cycles, so the blank requires a word meaning to interfere with or disturb a process. "Disrupt" means to interrupt the normal course of something, which directly matches the described fragmentation of sleep architecture. "Abbreviate" means to shorten in duration or length, but the passage emphasizes fragmentation of cycles rather than a reduction in total sleep time. "Diagnose" means to identify a medical condition, which makes no sense as something vibrations do to sleep architecture. "Fabricate" means to construct or invent something, which is incoherent in the context of vibrations affecting sleep patterns.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RJPCEW', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Paleontologist Jorge Mendez has proposed that the mass extinction at the end of the Permian period, roughly 252 million years ago, was triggered primarily by massive volcanic eruptions in what is now Siberia. The eruptions, he argues, released enough sulfur dioxide and carbon dioxide to acidify oceans and destabilize global climate systems within a few thousand years.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S9BYTB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Historian Claudette Renard argues that the popular narrative of the 1848 revolutions as spontaneous uprisings obscures the years of clandestine organizing that preceded them. Far from erupting without warning, the movements were __________ by networks of exiled intellectuals who circulated banned pamphlets and coordinated across national borders.', $lyceon_json$[{"key":"A","text":"orchestrated"},{"key":"B","text":"witnessed"},{"key":"C","text":"survived"},{"key":"D","text":"condemned"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts the idea that the revolutions were spontaneous with the claim that exiled intellectuals deliberately organized them through pamphlets and cross-border coordination. "Orchestrated" means deliberately arranged and directed, which precisely captures the passage''s emphasis on intentional, coordinated planning behind the movements. "Witnessed" means merely observed, which contradicts the passage''s point that intellectuals actively shaped the movements rather than passively watching them. "Survived" means endured or lived through, which could relate to the intellectuals'' experience but does not logically describe what they did to the movements themselves. "Condemned" means publicly denounced, which contradicts the passage''s depiction of intellectuals supporting and organizing the movements.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SQNULD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ornithologist Priya Nagarajan spent eleven months tracking the migration routes of bar-tailed godwits across the Pacific ______ her findings revealed that individual birds consistently returned to the same coastal mudflats each spring.', $lyceon_json$[{"key":"A","text":"Pacific, her"},{"key":"B","text":"Pacific her"},{"key":"C","text":"Pacific. Her"},{"key":"D","text":"Pacific her,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence contains two independent clauses: one about Nagarajan tracking migration routes and another about her findings. A period after "Pacific" correctly separates these two independent clauses into distinct sentences. Using a comma after "Pacific" creates a comma splice, which incorrectly joins two independent clauses with only a comma. Omitting punctuation entirely produces a run-on sentence. Placing a comma after "her" rather than between the clauses fails to address the boundary between the two independent clauses and also produces a run-on.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UF84AO', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Dara Okonkwo has documented that microfinance programs in sub-Saharan Africa frequently fail to produce long-term income gains for borrowers. Her longitudinal study of 1,340 participants across eleven Ghanaian districts found that average household income returned to pre-loan levels within twenty-six months of disbursement. Okonkwo attributes this pattern to the saturation of low-barrier markets: when dozens of borrowers in the same village invest in identical enterprises, such as phone-charging kiosks or roasted-plantain stands, competition erodes margins. _______ she notes that the few participants who sustained income growth were those who used loans to enter less crowded trades requiring specialized skills, such as solar panel installation or veterinary pharmaceuticals.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'B', NULL, E'The preceding sentences establish Okonkwo''s explanation for why most microfinance borrowers fail to sustain income gains: market saturation erodes margins in low-barrier enterprises. The sentence after the blank presents a finding that logically follows from this explanation — participants who avoided saturated markets were the ones who succeeded. "Accordingly," correctly signals that this observation is a logical consequence of the market-saturation mechanism described earlier. "Specifically," suggests the sentence is narrowing or detailing the preceding general claim, but it is not elaborating on what market saturation looks like — it is reporting the predicted outcome of avoiding it. "Nonetheless," incorrectly introduces a concession or contrast, but the success of borrowers in less crowded trades is consistent with, not in tension with, the market-saturation explanation. "For instance," implies the sentence is an example of the immediately preceding claim about competition eroding margins, but the sentence actually describes the opposite outcome — sustained income growth — making it a consequence rather than an illustration of the saturation problem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X4VNU4', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of seventeenth-century nautical charts that a retired cartographer donated to the Rijksmuseum''s maritime archive last October ______ among the most detailed depictions of Southeast Asian coastlines from that era, according to a panel of historians who examined the documents.', $lyceon_json$[{"key":"A","text":"rank"},{"key":"B","text":"have ranked"},{"key":"C","text":"are ranking"},{"key":"D","text":"ranks"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject of the main clause is "collection," a singular noun, not the plural "charts" that appears in the intervening relative clause. The singular verb "ranks" correctly agrees with "collection." The plural form "rank" incorrectly treats "charts" as the subject. "Have ranked" is both plural and introduces the present perfect tense without contextual justification, since the passage describes the charts'' current status. "Are ranking" is plural and uses the progressive aspect, which is inappropriate for describing an enduring classification rather than an action in progress.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y4JNEG', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The renovation of the historic waterfront warehouses along the Motlawa River in Gdańsk ______ expected to take approximately seventeen months, according to the municipal planning commission''s most recent timeline.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"were"},{"key":"C","text":"is"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "renovation," a singular noun. The intervening prepositional phrase "of the historic waterfront warehouses along the Motlawa River in Gdańsk" does not change the number of the subject. Therefore, the singular verb "is" is required to agree with "renovation." The plural forms "are" and "have been" incorrectly treat the nearer noun "warehouses" as the subject. The past-tense "were" introduces an incorrect tense shift, since the passage describes a current expectation using the present tense ("according to the... most recent timeline").', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y8SXV1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'Paragraph 1: The baobab tree, native to sub-Saharan Africa, Madagascar, and northern Australia, can store up to 120,000 liters of water in its swollen trunk, enabling it to survive droughts lasting several years. This remarkable capacity has earned it the nickname "the tree of life" among communities that rely on it for water, food, and medicine during dry seasons.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YUG5I6', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best describes the main idea of the passage?', E'Researchers studying the migration patterns of Arctic terns have long noted the birds'' remarkable endurance. A 2019 tracking study led by ornithologist Petra Lindqvist attached lightweight GPS devices to 37 Arctic terns nesting in northern Iceland. The data revealed that these birds travel an average of 71,000 kilometers annually, making their round-trip journey from Arctic breeding grounds to Antarctic feeding areas the longest known migration of any animal. Lindqvist''s team also found that the terns consistently followed prevailing wind patterns rather than the shortest geographic route, a strategy that reduces energy expenditure despite adding thousands of kilometers to the total distance.', $lyceon_json$[{"key":"A","text":"Arctic terns follow wind patterns during migration because they lack the stamina to fly direct routes."},{"key":"B","text":"A tracking study showed that Arctic terns undertake extraordinarily long migrations and use wind-assisted routes to conserve energy."},{"key":"C","text":"Petra Lindqvist's research team was the first to document the migration of Arctic terns between the Arctic and Antarctic."},{"key":"D","text":"GPS tracking devices have transformed the study of bird migration by enabling precise measurement of flight distances."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on a tracking study that documented the extraordinary length of Arctic tern migrations and the birds'' energy-saving strategy of following wind patterns. The choice stating that a tracking study showed extraordinarily long migrations and wind-assisted routes captures both key findings. The claim that terns lack the stamina for direct routes misrepresents the passage, which says following wind patterns reduces energy expenditure—not that the birds are incapable of direct flight. The suggestion that Lindqvist''s team was the first to document Arctic tern migration overstates the passage, which says researchers have ''long noted'' these patterns. The claim about GPS devices transforming bird migration study focuses on technology rather than the passage''s actual subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z2MWNJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The village council voted not only to restore the crumbling medieval aqueduct that runs beneath the town center but also ______ a network of modern filtration stations along the original waterway, ensuring that the centuries-old infrastructure could serve a contemporary purpose.', $lyceon_json$[{"key":"A","text":"installing"},{"key":"B","text":"to install"},{"key":"C","text":"they installed"},{"key":"D","text":"installed"}]$lyceon_json$::jsonb, 'B', NULL, E'The correlative conjunction pair "not only... but also" requires parallel grammatical structures on both sides. Since the first element is the infinitive "to restore," the second element must also be an infinitive: "to install." The gerund "installing" breaks the parallel structure by switching from an infinitive to a participle form. The clause "they installed" introduces a new subject and finite verb, which is not parallel to the infinitive phrase. The simple past "installed" likewise fails to mirror the infinitive form and incorrectly shifts the tense, since the council voted to take future action rather than reporting a completed one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZE4IW8', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2023 monograph on regional fermentation practices, food anthropologist Ingrid Halvorsen identified three factors that distinguish Norwegian rakfisk production from superficially similar preservation methods found elsewhere in ______ the unusually low salinity of the brine, the reliance on autumn-caught freshwater trout rather than ocean fish, and the practice of fermenting the fish for a minimum of ninety-one days.', $lyceon_json$[{"key":"A","text":"Scandinavia, the"},{"key":"B","text":"Scandinavia the"},{"key":"C","text":"Scandinavia; the"},{"key":"D","text":"Scandinavia: the"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence promises "three factors" and then must introduce the list that specifies them. A colon after "Scandinavia" correctly signals that what follows is an elaboration or list fulfilling the promise of "three factors." A comma after "Scandinavia" produces a comma splice, since the preceding clause is independent and the list that follows functions as a series of noun phrases introduced without a proper signal. Omitting punctuation entirely creates a run-on. A semicolon requires an independent clause on both sides, but the list of three noun phrases ("the unusually low salinity," "the reliance," and "the practice") does not constitute an independent clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
